+		scx_task_unlink_from_dsq(p, &rq->scx.local_dsq);
+		scx_move_local_task_to_local_dsq(scx_task_sched(p), p,
+					SCX_ENQ_HEAD | SCX_ENQ_PREEMPT | SCX_ENQ_IGNORE_CAPS,
+					&rq->scx.local_dsq, rq);
+	}
+out_arm:
+	scx_rescue_timer_arm(rq);
+}
