diff --git a/fsck/segment.c b/fsck/segment.c
index 46dc747..43f85ec 100644
--- a/fsck/segment.c
+++ b/fsck/segment.c
@@ -770,15 +770,32 @@ int update_block(struct f2fs_sb_info *sbi, void *buf, u32 *blkaddr,
