index 559b04f4387e..a8ee304bdcc0 100644
--- a/tools/power/cpupower/lib/cpupower.c
+++ b/tools/power/cpupower/lib/cpupower.c
@@ -214,11 +214,17 @@ int get_cpu_topology(struct cpupower_topology *cpu_top)
